INSERT INTO public.recipes (slug,name,description,region,course,diet_type,meal_types,audience,min_age_months,max_age_months,prep_minutes,cook_minutes,servings,serving_size,calories,protein,carbohydrates,fat,fiber,sugar,sodium,allergens,suitable_for,texture,flavors,key_ingredients,ingredients,steps,tips,image)
SELECT 'baby-' || trim(both '-' from lower(regexp_replace(n,'[^a-zA-Z0-9]+','-','g'))), n, de, r, 'Baby Food',
  CASE d WHEN 'vg' THEN 'vegan' WHEN 'v' THEN 'vegetarian' WHEN 'e' THEN 'eggetarian' ELSE 'non_vegetarian' END,
  array_remove(ARRAY[
    CASE WHEN position('B' in m)>0 THEN 'breakfast' END,
    CASE WHEN position('L' in m)>0 THEN 'lunch' END,
    CASE WHEN position('D' in m)>0 THEN 'dinner' END,
    CASE WHEN position('S' in m)>0 THEN 'snack' END], NULL),
  'baby', mi, mx, pm, cm, 1, ss, k, p, cb, f, fi, su, na,
  CASE WHEN a='' THEN '{}'::text[] ELSE string_to_array(a,'|') END,
  '{}'::text[], tx,
  string_to_array(fl,'|'), string_to_array(ki,'|'), string_to_array(ing,'|'), string_to_array(st,'|'), tip, 'baby'
FROM (VALUES
('Rice Kanji','Smooth runny rice porridge - a gentle first food.','South Indian','vg','BL',6,8,5,15,'3-4 tbsp',40,0.8,9,0.1,0.2,0,2,'','puree','mild','rice','2 tbsp rice|1 cup water','Wash rice well and soak for 15 minutes|Cook in water until very soft|Mash and strain to a smooth, runny porridge|Cool to lukewarm and offer 1-2 tsp at first','Introduce one new food every 3 days and watch for reactions.'),
('Moong Dal Water','Strained yellow moong dal soup for first tastes.','North Indian','vg','L',6,8,5,15,'3-4 tbsp',35,2.5,6,0.1,1,0,3,'','puree','mild','moong dal','2 tbsp split yellow moong dal|1 cup water|Pinch of turmeric','Wash dal and soak 20 minutes|Pressure cook with water and turmeric until very soft|Mash well and strain the liquid|Serve lukewarm; move to mashed dal after a week','No salt or sugar before 12 months.'),
('Stewed Apple Puree','Silky steamed apple puree.','Pan-Indian','vg','BS',6,12,5,10,'3-4 tbsp',35,0.2,9,0.1,1.5,7,1,'','puree','sweet','apple','1 sweet apple|2-3 tbsp water','Peel, core and chop the apple|Steam or cook in water until very soft|Blend to a smooth puree|Cool and serve','Steaming keeps more vitamins than boiling.'),
('Banana Mash','No-cook ripe banana mash.','Pan-Indian','vg','BS',6,12,2,0,'1/2 small banana',45,0.5,11,0.2,1.3,6,1,'','puree','sweet','banana','1/2 ripe banana (elaichi or robusta)|1-2 tsp breast milk or formula (optional)','Choose a ripe banana with brown spots|Peel and mash with a fork until smooth|Thin with breast milk or formula if needed|Serve immediately','Ripe bananas are easy to digest and naturally sweet.'),
('Carrot Puree','Bright steamed carrot puree.','Pan-Indian','vg','L',6,12,5,10,'3-4 tbsp',20,0.5,4.5,0.1,1.4,2.2,35,'','puree','sweet|mild','carrot','1 medium carrot|Water for steaming','Peel and chop the carrot|Steam for 10 minutes until very soft|Blend with a little of the steaming water|Cool to lukewarm','Rich in beta-carotene for healthy eyes.'),
('Sweet Potato Mash','Creamy mashed sweet potato.','Pan-Indian','vg','LD',6,12,5,15,'3-4 tbsp',45,0.8,10,0.1,1.5,2,15,'','puree','sweet','sweet potato','1 small sweet potato|Breast milk, formula or water to thin','Wash, peel and cube the sweet potato|Steam or pressure cook until soft|Mash and thin to a smooth texture|Serve lukewarm','A filling, iron-friendly vegetable.'),
('Sprouted Ragi Porridge','Calcium-rich finger-millet porridge.','South Indian','vg','B',6,24,5,10,'1/2 cup (100g)',70,1.8,14,0.5,1.5,0.5,3,'','puree','mild','ragi','1 tbsp sprouted ragi flour|1/2 cup water|Breast milk or formula to thin (optional)|Pinch of cardamom','Mix ragi flour in a little water to a lump-free paste|Add the remaining water and cook on low heat 5-7 minutes, stirring|Cool and thin with breast milk or formula if needed|After 1 year, add a little date paste for sweetness','Ragi is rich in calcium and iron for growing bones.'),
('Pumpkin Moong Khichdi','Mashed rice, moong dal and pumpkin.','North Indian','v','LD',7,12,5,15,'1/2 cup',90,3.5,15,1.8,1.5,1,4,'dairy','mashed','mild','rice|moong dal|pumpkin|ghee','2 tbsp rice|1 tbsp moong dal|1/4 cup pumpkin cubes|Pinch of turmeric and cumin|1/4 tsp ghee|1.5 cups water','Wash rice and dal and soak 20 minutes|Pressure cook with pumpkin, turmeric and water for 4-5 whistles|Mash well and stir in ghee|Do not add salt before 1 year','A complete first meal with carbs, protein and healthy fat.'),
('Daliya Fruit Porridge','Broken-wheat porridge sweetened with fruit.','North Indian','vg','B',7,24,5,15,'1/2 cup',85,2.5,17,0.6,2.2,3,2,'gluten','mashed','mild|sweet','broken wheat|apple','2 tbsp fine daliya|1 cup water|2 tbsp apple puree or mashed banana','Dry roast daliya for 2 minutes|Cook in water till very soft (or pressure cook 3 whistles)|Blend or mash to suit your baby|Stir in fruit puree for natural sweetness','Whole grain fibre helps prevent constipation.'),
('Oats Banana Porridge','Smooth oats cooked with ripe banana.','Pan-Indian','vg','B',8,60,2,8,'1/2 cup',100,3,18,1.8,2.4,6,3,'','mashed','sweet','oats|banana','2 tbsp quick oats, powdered|1/2 cup water (or milk after 1 year)|1/2 ripe banana','Cook powdered oats in water for 3-4 minutes, stirring|Mash banana and stir it in|Cool to lukewarm|Thin with breast milk or formula if needed','Sweet without any added sugar.'),
('Idli Dal Mash','Soft idli mashed with warm moong dal.','South Indian','v','BL',8,24,5,0,'1 idli + 2 tbsp dal',80,3,15,0.5,1,0.3,20,'dairy','mashed','mild','rice|urad dal|moong dal','1 soft idli from salt-free batter|2 tbsp cooked moong dal|1/4 tsp ghee','Steam idli from a batter portion kept aside before adding salt|Crumble and mash with warm dal|Add ghee and mix to a soft consistency|Offer small spoonfuls; older babies can hold small idli pieces','Fermented foods are gentle on tiny tummies.'),
('Baby Curd Rice','Mashed rice with fresh homemade curd.','South Indian','v','L',8,24,5,0,'1/2 cup',95,3,15,2.5,0.2,2,15,'dairy','mashed','mild','rice|curd','3 tbsp soft cooked rice|2 tbsp fresh homemade curd|Pinch of cumin powder','Mash warm rice well|Cool to room temperature|Mix in fresh, non-sour curd and cumin|Serve immediately','Curd is fine from 8 months; plain cow milk as a drink only after 1 year.'),
('Soft Scrambled Egg','Fully cooked soft egg crumbles.','Pan-Indian','e','B',8,60,2,5,'1 egg',80,6,0.5,6,0,0.3,65,'egg|dairy','mashed','mild','egg','1 egg|1 tbsp breast milk, formula or milk (milk after 1 year)|1/4 tsp ghee','Whisk the egg with milk|Melt ghee in a pan on low heat|Stir gently until fully cooked with no runny parts|Cool and break into small soft pieces','Always cook eggs fully for babies.'),
('Chicken Veg Mash','Tender chicken mashed with potato and carrot.','Pan-Indian','n','LD',8,24,10,20,'1/2 cup',90,9,6,3,1,1,30,'','mashed','mild|savory','chicken|carrot|potato','50 g boneless chicken|1 small potato, 1 small carrot|Pinch of cumin, 1 small garlic clove|1 cup water','Cut chicken and vegetables into small pieces|Pressure cook with water, garlic and cumin for 4 whistles|Blend or mash with some stock to the right texture|Check carefully for bones before serving','Good source of iron and zinc for growth.'),
('Fish Rice Mash','Flaked steamed fish with soft rice.','East Indian','n','L',9,24,10,15,'1/2 cup',100,7,12,2.5,0.4,0.2,35,'fish|dairy','mashed','mild','fish|rice','30 g boneless fish fillet (rohu or pomfret)|3 tbsp soft rice|1/4 tsp ghee|Pinch of turmeric','Steam fish with turmeric for 8 minutes|Flake and remove every bone carefully|Mash with soft rice and ghee|Serve warm','Fish provides DHA for brain development.'),
('Paneer Spinach Mash','Soft paneer with pureed spinach.','North Indian','v','LD',9,24,5,10,'1/3 cup',85,5,3,6,1,0.8,25,'dairy','mashed','mild','paneer|spinach','2 tbsp homemade paneer|1/4 cup spinach leaves|1/4 tsp ghee|Pinch of cumin','Blanch spinach and puree|Crumble paneer finely|Warm ghee, add cumin, spinach and paneer and cook 2 minutes|Mash to a soft texture','Iron from spinach plus protein and calcium from paneer.'),
('Steamed Veggie Fingers','Soft steamed vegetable sticks for little hands.','Pan-Indian','vg','S',9,24,5,10,'1/2 cup',30,1,6,0.2,2,2.5,30,'','finger_food','mild|sweet','carrot|beans|sweet potato','1 carrot|5 French beans|1 small sweet potato','Cut vegetables into finger-length sticks|Steam until soft enough to squash between your fingers|Cool to lukewarm|Offer as finger food while seated and supervised','Self-feeding builds motor skills.'),
('Homemade Sathu Maavu Porridge','Multigrain health-mix porridge.','South Indian','vg','B',8,60,5,10,'1/2 cup',95,3,17,1.5,2,0.5,3,'tree_nuts','mashed','mild','ragi|millets|moong dal|almond','2 tbsp homemade sathu maavu (roasted ragi, rice, millets, moong and almond powder)|1/2 cup water|Breast milk or formula to thin','Mix the powder with a little water to a smooth paste|Add the remaining water and cook 5 minutes on low heat, stirring|Cool and thin to the right consistency|Add date paste after 1 year if desired','Give nuts only as fine powder, never whole, before age 5.'),
('Ragi Banana Pancakes','Soft mini pancakes, great finger food.','South Indian','vg','BS',10,60,5,10,'2 mini pancakes',110,2.5,22,1.8,2.5,6,3,'','finger_food','sweet','ragi|banana','3 tbsp ragi flour|1/2 ripe banana, mashed|Water to make a batter|Pinch of cardamom|1/2 tsp oil','Mix ragi, banana, cardamom and water to a thick batter|Spread small rounds on a non-stick pan with a little oil|Cook on low heat 2 minutes each side|Cool and cut into strips for little hands','No sugar needed - banana sweetens it.'),
('Mini Moong Chilla','Soft moong dal pancakes with carrot.','North Indian','vg','BS',12,60,5,10,'2 mini chillas',120,7,16,3,3,1,40,'','finger_food','mild','moong dal|carrot','1/4 cup split moong dal, soaked 2 hours|2 tbsp grated carrot|Pinch of cumin|1/2 tsp oil','Grind soaked dal to a smooth batter|Mix in carrot and cumin|Make small thick chillas on a non-stick pan|Cook well on both sides and cut into strips','Plant protein in a toddler-friendly shape.'),
('Toddler Veg Khichdi','Soft family-style khichdi with vegetables.','Pan-Indian','v','LD',12,60,10,20,'3/4 cup',160,6,26,3.5,3,1.5,120,'dairy','soft','mild|savory','rice|moong dal|vegetables|ghee','1/4 cup rice|2 tbsp moong dal|1/2 cup carrot, peas and beans|1/2 tsp ghee, pinch of cumin and turmeric|Tiny pinch of salt (after 1 year)','Wash rice and dal and soak 20 minutes|Saute cumin and vegetables in ghee|Add rice, dal, turmeric, a tiny pinch of salt and 3 cups water|Pressure cook 4 whistles and mash lightly','Can be shared with the whole family before adding spices.'),
('Toddler Sooji Upma','Soft semolina upma with vegetables.','South Indian','vg','B',12,60,5,10,'1/2 cup',130,3.5,20,4,1.5,1,90,'gluten','soft','mild','semolina|vegetables','3 tbsp roasted sooji|2 tbsp finely chopped carrot and peas|1/2 tsp oil, pinch of mustard seeds|Tiny pinch of salt|3/4 cup water','Heat oil, splutter mustard and saute vegetables|Add water and salt and bring to a boil|Add sooji slowly, stirring to avoid lumps|Cook covered 3 minutes until soft','Keep it soft and moist for easy swallowing.'),
('Beetroot Paratha Strips','Colourful soft paratha strips.','North Indian','v','BLD',12,60,10,10,'1 small paratha',140,4,20,5,2.5,2,90,'gluten|dairy','finger_food','mild','wheat|beetroot','1/2 cup whole wheat flour|3 tbsp grated beetroot|1/2 tsp ghee|Pinch of ajwain','Knead flour with beetroot and ajwain, adding water as needed|Roll small thick parathas|Cook on a tawa with a little ghee until done|Cut into strips and serve with curd','Bright colours make vegetables fun for picky eaters.'),
('Mild Chicken Pulao','Gently spiced chicken and vegetable rice.','Pan-Indian','n','L',12,60,10,20,'3/4 cup',190,11,24,5,1.5,1,140,'dairy','soft','mild|savory','rice|chicken|vegetables|ghee','1/4 cup rice|50 g boneless chicken, finely chopped|1/4 cup carrot and peas|1 tsp ghee, 1 small bay leaf, pinch of cumin|Tiny pinch of salt|3/4 cup water','Saute bay leaf, cumin and chicken in ghee for 3 minutes|Add washed rice, vegetables, salt and water|Pressure cook 3 whistles|Remove the bay leaf and fluff gently','Protein-rich meal for active toddlers.')
) AS t(n,de,r,d,m,mi,mx,pm,cm,ss,k,p,cb,f,fi,su,na,a,tx,fl,ki,ing,st,tip);